<?php require __DIR__.'/bootstrap.php';require __DIR__.'/webauthn.php';$email=strtolower(trim($_POST['email']??$_GET['email']??''));$q=$pdo->prepare('SELECT id FROM users WHERE email=? AND status="active" LIMIT 1');$q->execute([$email]);$uid=(int)$q->fetchColumn();if(!$uid)json_out(['error'=>'Conta não encontrada.'],404);$q=$pdo->prepare('SELECT credential_id FROM webauthn_credentials WHERE user_id=?');$q->execute([$uid]);$allow=[];foreach($q as $row)$allow[]=['type'=>'public-key','id'=>b64u_encode($row['credential_id'])];if(!$allow)json_out(['error'=>'Cadastre a biometria primeiro dentro da sua conta.'],422);$challenge=random_bytes(32);$_SESSION['webauthn_login_challenge']=b64u_encode($challenge);$_SESSION['webauthn_login_user']=$uid;json_out(['publicKey'=>['challenge'=>b64u_encode($challenge),'rpId'=>webauthn_rp_id(),'allowCredentials'=>$allow,'userVerification'=>'required','timeout'=>60000]]);
